"""Make the on-site rehearsal sheet. Set CHROME to an installed Chromium binary."""
from pathlib import Path
import os
from playwright.sync_api import sync_playwright
root=Path(__file__).resolve().parents[1]/'studies'
def asset(file):return (root/file).as_uri()
html=f"""<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Birth in Water — gallery rehearsal sheets</title><style>
@page{{size:A3 landscape;margin:0}}*{{box-sizing:border-box}}body{{margin:0;color:#243832;font-family:Arial,sans-serif}}article{{width:420mm;height:297mm;padding:13mm 17mm;page-break-after:always}}article:last-child{{page-break-after:auto}}h1,h2,h3,p{{margin:0}}h1{{font:normal 32pt Georgia,serif}}h2{{font:normal 24pt Georgia,serif;margin-bottom:4mm}}h3{{font-size:13pt;margin:3mm 0 1mm}}p,li,td,th{{font-size:11pt;line-height:1.4}}small{{font-size:10pt}}header{{border-bottom:1px solid #9fb0a7;padding-bottom:3mm;margin-bottom:3mm}}figure{{margin:0}}.two{{display:grid;grid-template-columns:1fr 1fr;gap:9mm}}.map{{width:100%;height:125mm;object-fit:contain}}.view{{width:100%;height:76mm;object-fit:contain}}table{{border-collapse:collapse;width:100%;margin:3mm 0 5mm}}th,td{{text-align:left;vertical-align:top;border-bottom:1px solid #aebcb4;padding:2.5mm}}.entry td{{height:12mm}}.fine{{color:#455e54}}.line{{display:inline-block;border-bottom:1px solid #64796d;min-width:55mm}}ul{{margin:1mm 0 4mm;padding-left:6mm}}footer{{margin-top:3mm;font-size:10pt}}</style></head><body>
<article><header><h1>Birth in Water</h1><p>Room rehearsal &nbsp; / &nbsp; Plan, section and elevation &nbsp; / &nbsp; Working dimensions for an 8 × 6 m mock-up</p></header>
<figure><img class="map" src="{asset('room-proposal.svg')}"></figure><div class="two"><figure><img class="view" src="{asset('north-elevation.svg')}"></figure><figure><img class="view" src="{asset('seated-views.svg')}"></figure></div>
<div class="two"><p><b>Set out the viewing bay.</b> Tape the 1.6 m turning circle and the south bypass. Place a chair or wheelchair at the lateral mark. Move a fifth visitor into the diagonal; recover the view without asking the seated visitor to move.</p><p><b>Look through filled glass.</b> Project black, then a bright population frame. At the front pane, the proposed standing ray passes about 7 mm below the assumed waterline. Record the obstruction before choosing the plinth height. The 721 mm CAD shell cannot turn broadside in the model’s 631 mm clear width. Tape the actual hull’s turning envelope before ordering glass.</p></div></article>
<article><header><h1>Run one complete visit</h1><p>Venue <span class="line">&nbsp;</span> &nbsp; Date <span class="line">&nbsp;</span> &nbsp; Operator <span class="line">&nbsp;</span> &nbsp; Floor host <span class="line">&nbsp;</span></p></header>
<h2>Arrivals to rehearse</h2><table><tr><th>Position and time</th><th>Observe</th><th>On-site result / change</th></tr>
<tr><td>Exhibition film at 48 s. Stay 12 s.</td><td>Can a visitor identify the opening and the larger body's turn without being told to touch the tank?</td><td>______________________________</td></tr>
<tr><td>Exhibition film at 72.5 s. Stay 25 s.</td><td>The visitor crosses the loop boundary and can leave before a release. Can they tell recorded and live time apart?</td><td>______________________________</td></tr>
<tr><td>One seated, four standing, one entering.</td><td>Begin at film 42 s. Test the blocked opening and the turn toward the film from the visitor's own eye height.</td><td>______________________________</td></tr>
<tr><td>Mute at 42 s. Stay 16 s. No touch.</td><td>Can a visitor see both hulls move and follow the change in the low pitch from the captions?</td><td>______________________________</td></tr>
<tr><td>Pause pump mid-visit. Film continues.</td><td>Post the actual tank state. Time the staff response and route. Restart only after the operator confirms a working cycle.</td><td>______________________________</td></tr></table>
<div class="two"><div><h3>Record actual reset duration</h3><p>Clock each step from retrieval to a confirmed release. End a failed trial with its real status.</p><table class="entry"><tr><th>Take</th><th>Retrieve</th><th>Load / prime</th><th>Release</th><th>Total / fault</th></tr><tr><td>1</td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td></tr></table></div><div><h3>Lights and listening positions</h3><ul><li>Compare pump only, film only and both at the tank and at the door. Identify room resonance or vibration entering the plinth.</li><li>Check rail and glare against both eye heights with venue access staff. Agree a level for circulation lighting.</li><li>Walk retrieval, refill and dry-tool routes with the operator. Confirm water handling, power, venue load approval, coverage during breaks and shutdown responsibility.</li></ul><p>Adjustment to test next <span class="line">&nbsp;</span></p></div></div><footer>Time offsets refer to the 79.15 s exhibition edit. The physical apparatus has a separate cycle. Record visitor observations only with consent.</footer></article></body></html>"""
with sync_playwright() as p:
 b=p.chromium.launch(executable_path=os.environ.get('CHROME'),args=['--no-sandbox','--allow-file-access-from-files'])
 page=b.new_page();page.goto((root/'room.html').as_uri());page.set_content(html,wait_until='load')
 assert page.evaluate('Array.from(document.images).every(i=>i.naturalWidth>0)')
 page.pdf(path=str(root/'gallery-rehearsal.pdf'),prefer_css_page_size=True,print_background=True,tagged=True)
 b.close()
